function blank(kind){return {kind,date:today(),currency:'TRY',channel:'CASH',partyId:'',referenceId:'',settlementDocumentId:'',from:'BANK',to:'CASH',sourceCurrency:'TRY',targetCurrency:'TRY',reason:'',amount:'',taxRate:'0',counted:{TRY:'',USD:'',EUR:''},items:[],supplierInvoiceNumber:'',correctionReason:'',salesPolicyVersion:kind==='sale'?2:undefined,fulfillmentPolicyVersion:kind==='sale'?1:undefined,dueDate:dueInDays(30),minimumExceptionReason:'',priceExceptionReason:'',creditExceptionReason:'',returnFlow:{reasonCode:kind==='delivery-correction'?'MISSING':'',boxCount:kind==='delivery-correction'?'0':'',countedBy:'Personel',note:''},countSession:{countedBy:'Personel',note:'',investigation:{}},intake:{boxCount:'',countedBy:'Personel',note:'',samples:{},expected:{},unknownItems:[]}};}
function taskForm(state,screenId,payload={}){
 const form={...blank(payload.kind||routeKinds[screenId]||'receipt'),...Object.fromEntries(Object.entries(payload).filter(([k])=>['kind','partyId','currency','amount','settlementDocumentId'].includes(k)))};
 const source=state.documents.find(d=>d.id===Number(payload.referenceId));
 if(source){form.referenceId=String(source.id);form.partyId=source.partyId;form.currency=source.currency;form.taxRate=String(source.taxRate||0);form.items=(source.kind==='receipt'?remainingReceipt(state,source).filter(l=>l.remaining>0):source.items).map(l=>({productId:l.productId,quantity:String(source.kind==='receipt'?l.remaining:l.quantity),unitPrice:source.kind==='receipt'?(source.currency==='TRY'?String(state.products.find(p=>p.id===l.productId).cost/100):''):String(l.unitPrice/100),discount:String(l.discount||0)}));}
 if(payload.productId){const product=state.products.find(p=>p.id===payload.productId);if(product)form.items=[{productId:product.id,quantity:'1',unitPrice:String(product.cost/100),discount:'0'}];}
 return form;
}
