 const needed=kind=>roleViewId==='satis'&&['collection','payment','customer-refund','supplier-refund','expense','cash-open','cash-close','transfer','cash-adjustment'].includes(kind)?'finance.accounting-only':({receipt:'purchase.create',purchase:'purchase.finalize',sale:'sales.finalize','sales-return':'sales.finalize','delivery-correction':'sales.finalize','purchase-return':'purchase.finalize',count:'stock.adjust',collection:'finance.collection',payment:'finance.payment','customer-refund':'finance.payment','supplier-refund':'finance.collection',expense:'finance.payment','cash-open':'finance.payment','cash-close':'finance.payment',transfer:'finance.payment','cash-adjustment':'finance.payment'}[kind]);
 const busy=useRef(false);
