 function edit(doc){setFormOpen(true);setPendingScan(null);setBarcodeSearch('');setDirty(false);setForm({...doc,correctionReason:'',intake:doc.intake?{...doc.intake,boxCount:String(doc.intake.boxCount)}:blank(doc.kind).intake,returnFlow:doc.returnFlow?{...doc.returnFlow,boxCount:String(doc.returnFlow.boxCount)}:blank(doc.kind).returnFlow,countSession:doc.countSession||blank(doc.kind).countSession,counted:Object.fromEntries(currencies.map(c=>[c,String((doc.counted?.[c]||0)/100)])),amount:String(doc.amount/100),items:doc.items.map(l=>({...l,quantity:String(l.quantity),unitPrice:String(l.unitPrice/100),discount:String(l.discount)}))});setDraftId(doc.id);setSelected(doc.id);}
 function reviewAction(type,doc){run(async()=>{if(!permissions.includes(needed(doc.kind)))throw Error('İnceleme işlemi için yetkiniz yok.');await dispatchOperations({type,id:doc.id,reason:cancelReason});setCancelReason('');setMessage(type==='submit-review'?'Belge muhasebe kontrolüne gönderildi.':'Muhasebe düzeltme için personele geri gönderdi.');});}
 function receiptAction(type,doc,extra={}){run(async()=>{await dispatchOperations({type,id:doc.id,...extra});setMessage(type==='submit-receipt'?'Sayım muhasebe kontrolüne gönderildi.':type==='return-receipt'?'Sayım gerekçesiyle personele geri gönderildi.':'Barkod ürün kartına eşleştirildi.');});}
 const scope=routeKinds[screenId];
 const inScope=d=>scope==='receipt'?d.kind==='receipt':scope==='purchase'?['purchase','purchase-return'].includes(d.kind):scope==='sale'?['sale','sales-return','delivery-correction'].includes(d.kind):scope==='count'?d.kind==='count':scope==='collection'?['collection','payment','order-payment','customer-refund','supplier-refund','expense','cash-open','cash-close','cash-adjustment','transfer','finance-reversal'].includes(d.kind):true;
 const docs=state.documents.filter(d=>inScope(d)&&(filter==='ALL'||d.status===filter)&&(currencyFilter==='ALL'||d.currency===currencyFilter)&&(!dateFrom||d.date>=dateFrom)&&(!dateTo||d.date<=dateTo)&&`${d.number} ${kinds[d.kind]} ${partyName(d.partyId)}`.toLocaleLowerCase('tr').includes(search.toLocaleLowerCase('tr'))).slice().reverse();
